const handleVenueTypeSelect = async (type: 'home' | 'indoor' | 'outdoor' | 'specialty') => {
  setSelectedVenueType(type);

  if (type === 'home') {
    return; // Show home venue options
  }

  // Fetch venues for other types using the new local venues API
